/* From Uiverse.io by zanina-yassine - Tags: loader */
.__UIV_SCOPE__ .master-container {
  margin: 0;
  padding: 20px 40px;
  background-color: #131516;
  display: grid;
  border-radius: 13px;
  border: 1px solid #2c2d2e;
  transform: scale(0.7);
}

.__UIV_SCOPE__ .container {
  width: 300px;
  height: 300px;
  position: relative;
  margin: auto;
  border-radius: 50%;
  border: 2px solid white;
  overflow: hidden;
}

.__UIV_SCOPE__ .crescent {
  position: relative;
  height: 50px;
  width: 50px;
  border-radius: 50%;
  left: calc(50% - 25px);
  top: 12px;
  overflow: hidden;
  animation: rotate 3s cubic-bezier(0.15, 0.83, 0.66, 1) infinite;
}

.__UIV_SCOPE__ .crescent span:nth-child(2) {
  position: absolute;
  display: block;
  width: 100%;
  height: 100%;
  box-shadow: inset 0 0 0 2px white;
  border-radius: 50%;
}

.__UIV_SCOPE__ .crescent span:nth-child(1) {
  background-color: #131516;
  position: absolute;
  left: 40%;
  display: block;
  width: calc(70% - 6px);
  height: calc(70% - 6px);
  box-shadow: inset 0 0 0 2px white;
  border-radius: 50%;
  z-index: 9;
}

.__UIV_SCOPE__ .star {
  position: absolute;
  overflow: hidden;
  border-radius: 50%;
  height: 20px;
  width: 20px;
}

.__UIV_SCOPE__ .star span:nth-child(1)::before {
  content: "";
  border: 2px solid white;
  height: 50%;
  width: 50%;
  border-top-color: transparent;
  border-left-color: transparent;
  border-radius: 0% 0% 100% 10%;
  display: block;
  left: -3px;
  top: -3px;
  position: absolute;
}

.__UIV_SCOPE__ .star span:nth-child(1)::after {
  content: "";
  border: 2px solid white;
  height: 50%;
  width: 50%;
  border-bottom-color: transparent;
  border-left-color: transparent;
  border-radius: 0% 100% 0% 0%;
  display: block;
  left: -3px;
  bottom: -3px;
  position: absolute;
}

.__UIV_SCOPE__ .star span:nth-child(2)::before {
  content: "";
  border: 2px solid white;
  height: 50%;
  width: 50%;
  border-top-color: transparent;
  border-right-color: transparent;
  border-radius: 0% 0% 0% 100%;
  display: block;
  right: -3px;
  top: -3px;
  position: absolute;
}

.__UIV_SCOPE__ .star span:nth-child(2)::after {
  content: "";
  border: 2px solid white;
  height: 50%;
  width: 50%;
  border-bottom-color: transparent;
  border-right-color: transparent;
  border-radius: 100% 0% 0% 0%;
  display: block;
  right: -3px;
