.__UIV_SCOPE__ .hill {
  display: block;
  width: 140%;
  height: 100%;
  border: 2px solid white;
  border-radius: 50%;
  bottom: -40%;
  position: relative;
  left: -20%;
  background-size: 3%;
  background-repeat: repeat;
  opacity: 0.7;
}

.__UIV_SCOPE__ .fire-pit {
  width: 18px;
  height: 30px;
  position: absolute;
  left: calc(50% - 9px);
  bottom: 25px;
  z-index: 99;
}

.__UIV_SCOPE__ .fire {
  width: 0;
  height: 0;
  border: 9px solid transparent;
  border-bottom: 18px solid #ffffff;
  position: relative;
  top: -9px;
}

.__UIV_SCOPE__ .fire:after {
  content: "";
  position: absolute;
  left: -9px;
  top: 18px;
  width: 0;
  height: 0;
  border: 9px solid transparent;
  border-top: 9px solid #ffffff;
}

.__UIV_SCOPE__ .inner-fire {
  width: 0;
  height: 0;
  border: 4.5px solid transparent;
  border-bottom: 9px solid #131516;
  top: 4.5px;
  position: absolute;
  z-index: 9;
  left: -4.5px;
}

.__UIV_SCOPE__ .inner-fire:after {
  content: "";
  position: absolute;
  left: -4.5px;
  top: 9px;
  width: 0;
  height: 0;
  border: 4.5px solid transparent;
  border-top: 6px solid #131516;
}

.__UIV_SCOPE__ .log1 {
  background-color: white;
  height: 2px;
  transform: rotate(35deg);
  transform-origin: center;
  position: relative;
  left: -3px;
  bottom: -1.5px;
}

.__UIV_SCOPE__ .log2 {
  background-color: white;
  height: 2px;
  transform: rotate(-35deg);
  transform-origin: center;
  left: 3px;
  position: relative;
  bottom: -0px;
}

.__UIV_SCOPE__ .hut {
  width: 0;
  height: 0;
  border-left: 38px solid transparent;
  border-right: 38px solid transparent;
  border-bottom: 75px solid #131516;
  position: absolute;
  left: calc(50% - 37.6px);
  z-index: 11;
  bottom: 80px;
  transform: scale(1.3);
}

.__UIV_SCOPE__ .hut hr:nth-child(1) {
  height: 0px;
  position: absolute;
  width: 75px;
  bottom: -75px;
  left: calc(50% - 37.6px);
}

.__UIV_SCOPE__ .hut hr:nth-child(2) {
  height: 0px;
  position: absolute;
  width: 96px;
  bottom: -32px;
  left: -32px;
  transform: rotate(63.5deg);
  border: 1px solid white;
}

.__UIV_SCOPE__ .hut hr:nth-child(3) {
  height: 0px;
  position: absolute;
  width: 96px;
  bottom: -32px;
  right: -32px;
  transform: rotate(-63.5deg);
  border: 1px solid white;
}

.__UIV_SCOPE__ .hut hr:nth-child(4) {
  height: 0px;
  position: absolute;
  width: 60px;
  bottom: -60px;
  left: -30px;
  border: 0.5px solid white;
}

.__UIV_SCOPE__ .hut hr:nth-child(5) {
  height: 0px;
  position: absolute;
  width: 55px;
  bottom: -55px;
  left: -27.5px;
  border: 0.5px solid white;
}

.__UIV_SCOPE__ .hut hr:nth-child(6) {
  height: 0px;
  position: absolute;
  width: 50px;
  bottom: -50px;
  left: -25px;
  border: 0.5px solid white;
}

.__UIV_SCOPE__ .doorway {
  width: 0;
  height: 0;
  border-left: 22px solid transparent;
  border-right: 22px solid transparent;
  border-bottom: 42px solid #131516;
  position: relative;
  left: -22px;
  bottom: -32px;
}

.__UIV_SCOPE__ .doorway::before {
  content: "";
  border-left: 1px solid white;
  width: 0px;
  height: 48px;
  display: inline-block;
  transform: rotate(-27deg);
  left: 11px;
  position: absolute;
  bottom: -45px;
}

.__UIV_SCOPE__ .doorway::after {
  content: "";
  border-left: 1px solid white;
  width: 0px;
  height: 48px;
  display: inline-block;
  transform: rotate(27deg);
  left: -11px;
  position: absolute;
  bottom: -45px;
}

.__UIV_SCOPE__ .doorway > hr.split {
  height: 44px;
  width: 1px;
  position: absolute;
  left: 0px;
  top: 0;
  display: inline-block;
  background-color: white;
  border: 0;
}

/* Trees */
.__UIV_SCOPE__ .tree {
  position: absolute;
  width: 25px;
  height: 48px;
  z-index: 21;
  transform: scale(1.3);
}

.__UIV_SCOPE__ .tree .trunc {
  height: 48px;
  width: 1px;
  background-color: white;
  left: 12.5px;
  position: absolute;
  margin-top: 1.5px;
}

.__UIV_SCOPE__ .tree .leaves {
  height: 18px;
  width: 18px;
  transform: rotate(45deg);
  border-left: 1.5px solid white;
  border-top: 1.5px solid white;
  border-bottom: 0;
  border-right: 0;
  margin-bottom: -15px;
  margin-top: 5px;
  left: 4px;
  position: relative;
}

.__UIV_SCOPE__ .one {
  left: 30px;
  bottom: 90px;
}

.__UIV_SCOPE__ .two {
  right: 30px;
  bottom: 90px;
}

.__UIV_SCOPE__ .three {
  left: 80px;
  bottom: 115px;
}

.__UIV_SCOPE__ .four {
  right: 80px;
  bottom: 115px;
}

.__UIV_SCOPE__ .loading-text {
  color: white;
  font-family: 'Inter', sans-serif;
  display: block;
  text-align: center;
  padding: 20px 0 0 0;
  opacity: 0.8;
}

@keyframes glow {
  0% {
    transform: scale(0);
  }

  50% {
    transform: scale(1);
  }

  100% {
    transform: scale(0);
  }
}

@keyframes rotate {
  0% {
    transform: rotate(0);
  }

  50% {
    transform: rotate(10deg);
  }

  100% {
    transform: rota(0);
  }
}
